#!/usr/bin/env node

/**
 * validate-environmental-aspects-2568.mjs
 * ========================================
 * Schema + semantic validator for the CAT1-1.3 canonical dataset
 * (src/data/category1/environmental-aspects-2568.json), generated by
 * scripts/normalize-environmental-aspects-2568.mjs.
 *
 * SCHEMA checks:
 *   - top-level keys + contract envelope (year 2568, domain, sources)
 *   - record id patterns and uniqueness (act-*, ea-*, si-*, pl-*)
 *   - required fields, types, and valid enums per record kind
 *   - sourceTrace present on every record
 *
 * SEMANTIC checks:
 *   - no records sourced from the superseded output priority sheet
 *   - activity/process references resolve
 *   - Input/Output, Direct/Indirect, Normal/Abnormal/Emergency valid
 *   - significance consistent with the source assessment (register/priority)
 *   - M/H records retain control information (source provides it)
 *   - legal references preserved (Y/N), no invented mappings
 *   - project links reference only canonical projects (projects.json)
 *   - significant issues (1.3.2) derive from canonical aspect records (1.3.1)
 *   - no FY2567/FY2569 leakage in record values
 *
 * Usage: node scripts/validate-environmental-aspects-2568.mjs
 * Exit code: 0 on pass, 1 on failure.
 */

import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const DATA_PATH = resolve(ROOT, 'src', 'data', 'category1', 'environmental-aspects-2568.json');
const PROJECTS_PATH = resolve(ROOT, 'src', 'data', 'category1', 'projects.json');

const CANONICAL_PRIORITY_SHEETS = new Set(['จัดลำดับ (Input)', 'จัดลำดับ(Output) (29 สค68)']);
const SUPERSEDED_SHEET = 'จัดลำดับ(Output)';
const VALID_SIGNIFICANCE = new Set(['L', 'M', 'H']);
const VALID_VERIFICATION = new Set(['verified', 'reviewed', 'pending', 'unavailable']);

function readJSON(p) {
  return JSON.parse(readFileSync(p, 'utf8'));
}

function main() {
  const errors = [];
  const data = readJSON(DATA_PATH);
  const projectsData = readJSON(PROJECTS_PATH);
  const canonicalProjects = new Set(
    projectsData.records
      .filter((r) => r.kind === 'project' && r.indicatorCodes.includes('1.3.3'))
      .map((r) => r.id),
  );

  // ── Envelope ──────────────────────────────────────────────────
  if (data.schemaVersion !== '1.0.0') errors.push('schemaVersion must be 1.0.0');
  if (data.domain !== 'environmental-aspects-2568') errors.push(`domain mismatch: ${data.domain}`);
  if (data.year !== 2568) errors.push(`year must be 2568, got ${data.year}`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(data.updated))) errors.push(`updated must be an ISO date, got ${data.updated}`);
  for (const key of ['sources', 'versionDisposition', 'anomalies', 'activities', 'records', 'significantIssues', 'projectLinks', 'summary', 'gaps']) {
    if (!Array.isArray(data[key]) && !['summary'].includes(key)) errors.push(`missing or invalid "${key}"`);
  }

  const ids = new Set();

  // ── Activities ────────────────────────────────────────────────
  for (const [i, rec] of (data.activities || []).entries()) {
    const at = `activities[${i}]`;
    if (!/^act-\d+$/.test(rec.id)) errors.push(`${at}: id pattern act-N required, got "${rec.id}"`);
    if (ids.has(rec.id)) errors.push(`${at}: duplicate id ${rec.id}`);
    ids.add(rec.id);
    if (rec.kind !== 'activity') errors.push(`${at}: kind must be activity`);
    if (!rec.name) errors.push(`${at}: name required`);
    if (rec.year !== 2568) errors.push(`${at}: year must be 2568`);
    if (!rec.sourceTrace || !rec.sourceTrace.sourceFile || !rec.sourceTrace.sourceRow) errors.push(`${at}: sourceTrace incomplete`);
  }
  const activityIds = new Set(data.activities.map((a) => a.id));
  const activityByName = new Map(data.activities.map((a) => [a.name, a.id]));

  // ── Aspects ───────────────────────────────────────────────────
  const aspectsById = new Map();
  for (const [i, rec] of (data.records || []).entries()) {
    const at = `records[${i}] (${rec.id || '?'})`;
    if (!/^ea-\d+$/.test(rec.id)) errors.push(`${at}: id pattern ea-N required`);
    if (ids.has(rec.id)) errors.push(`${at}: duplicate id ${rec.id}`);
    ids.add(rec.id);
    aspectsById.set(rec.id, rec);
    if (rec.kind !== 'aspect') errors.push(`${at}: kind must be aspect`);
    if (rec.year !== 2568) errors.push(`${at}: year must be 2568`);
    if (!['1.3.1'].includes(rec.indicatorCodes?.join(',')) ) errors.push(`${at}: indicatorCodes must be exactly ['1.3.1']`);
    if (rec.categoryCode !== 'cat1') errors.push(`${at}: categoryCode must be cat1`);
    if (!rec.activityId || !activityIds.has(rec.activityId)) errors.push(`${at}: activityId "${rec.activityId}" does not resolve`);
    if (!rec.activity || activityByName.get(rec.activity) !== rec.activityId) errors.push(`${at}: activity name/id mismatch`);
    if (!['input', 'output'].includes(rec.inputOutput)) errors.push(`${at}: inputOutput must be input|output`);
    const expectedSheet = rec.inputOutput === 'input' ? 'Input' : 'Output';
    if (rec.sourceTrace?.sheet !== expectedSheet) errors.push(`${at}: sourceTrace.sheet must be ${expectedSheet} for inputOutput ${rec.inputOutput}`);
    if (!rec.aspect) errors.push(`${at}: aspect required`);
    if (!['direct', 'indirect'].includes(rec.directIndirect)) errors.push(`${at}: directIndirect must be direct|indirect`);
    if (!['normal', 'abnormal', 'emergency'].includes(rec.condition)) errors.push(`${at}: condition must be normal|abnormal|emergency`);
    if (!['Y', 'N'].includes(rec.applicableLaw)) errors.push(`${at}: applicableLaw must be Y|N`);
    if (!rec.impact || !rec.impactMeaning) errors.push(`${at}: impact and impactMeaning required`);
    const a = rec.assessment || {};
    if (!Array.isArray(a.likelihoodFactors) || a.likelihoodFactors.some((x) => typeof x !== 'number')) errors.push(`${at}: likelihoodFactors must be a number array`);
    if (!Array.isArray(a.severityFactors) || a.severityFactors.some((x) => typeof x !== 'number')) errors.push(`${at}: severityFactors must be a number array`);
    if (a.likelihoodTotal !== null && a.likelihoodTotal !== undefined && typeof a.likelihoodTotal !== 'number') errors.push(`${at}: likelihoodTotal must be a number or null`);
    if (a.severityTotal !== null && a.severityTotal !== undefined && typeof a.severityTotal !== 'number') errors.push(`${at}: severityTotal must be a number or null`);
    if (a.riskScore !== null && a.riskScore !== undefined && typeof a.riskScore !== 'number') errors.push(`${at}: riskScore must be a number or null`);
    for (const key of ['registerSignificance', 'prioritySignificance', 'significance']) {
      if (a[key] !== null && a[key] !== undefined && !VALID_SIGNIFICANCE.has(a[key])) errors.push(`${at}: assessment.${key} invalid "${a[key]}"`);
    }
    if (!['register', 'priority'].includes(a.significanceSource)) errors.push(`${at}: significanceSource must be register|priority`);
    if (typeof a.reclassified !== 'boolean') errors.push(`${at}: assessment.reclassified must be boolean`);

    // Significance consistency with the source assessment.
    if (a.significanceSource === 'priority' && a.prioritySignificance && a.significance !== a.prioritySignificance) {
      errors.push(`${at}: significance ${a.significance} must equal prioritySignificance ${a.prioritySignificance}`);
    }
    if (a.significanceSource === 'register' && a.significance !== a.registerSignificance) {
      errors.push(`${at}: significance ${a.significance} must equal registerSignificance ${a.registerSignificance}`);
    }
    if (a.registerSignificance && a.prioritySignificance && a.registerSignificance !== a.prioritySignificance && a.significance !== a.prioritySignificance) {
      errors.push(`${at}: when register and priority disagree, canonical significance must be the priority value`);
    }

    // Control: source provides controls on every row — M/H must retain them.
    if ((a.significance === 'M' || a.significance === 'H') && (!rec.controlMeasure || !rec.controlMeasure.text)) {
      errors.push(`${at}: M/H aspect must retain control information (source provides it)`);
    }
    if (rec.controlMeasure && !['register', 'priority'].includes(rec.controlMeasure.source)) errors.push(`${at}: controlMeasure.source invalid`);

    // Project reference only via canonical projects.
    if (rec.projectReference) {
      if (!canonicalProjects.has(rec.projectReference.projectId)) {
        errors.push(`${at}: projectReference.projectId "${rec.projectReference.projectId}" is not a canonical 1.3.3 project`);
      }
      const controlText = rec.controlMeasure ? rec.controlMeasure.text : '';
      if (!controlText) errors.push(`${at}: projectReference without control text is unsupported`);
    }

    // Source trace + superseded-sheet exclusion.
    const st = rec.sourceTrace || {};
    if (!st.sourceFile || !st.sheet || !st.sourceRow || !st.sourceVersion || !st.sourceDisposition) {
      errors.push(`${at}: sourceTrace incomplete (sourceFile/sheet/sourceRow/sourceVersion/sourceDisposition required)`);
    }
    if (st.prioritySheet === SUPERSEDED_SHEET) errors.push(`${at}: record sourced from superseded sheet ${SUPERSEDED_SHEET}`);
    if (st.prioritySheet && !CANONICAL_PRIORITY_SHEETS.has(st.prioritySheet)) errors.push(`${at}: unknown priority sheet "${st.prioritySheet}"`);
    const v = rec.verification || {};
    if (!VALID_VERIFICATION.has(v.status)) errors.push(`${at}: invalid verification.status "${v.status}"`);
    if (!rec.sourceRef) errors.push(`${at}: sourceRef required`);
  }

  // ── Significant issues (1.3.2) — derived, never a second registry ──
  const mhAspects = (data.records || []).filter((r) => r.assessment.significance === 'M' || r.assessment.significance === 'H');
  if (data.summary.significantCount !== mhAspects.length) errors.push(`summary.significantCount ${data.summary.significantCount} != M/H aspect count ${mhAspects.length}`);
  if ((data.significantIssues || []).length !== mhAspects.length) errors.push(`significantIssues.length must equal M/H aspect count (derived, no manual registry)`);
  for (const [i, si] of (data.significantIssues || []).entries()) {
    const at = `significantIssues[${i}] (${si.id || '?'})`;
    if (!/^si-\d+$/.test(si.id)) errors.push(`${at}: id pattern si-N required`);
    if (ids.has(si.id)) errors.push(`${at}: duplicate id`);
    ids.add(si.id);
    if (si.year !== 2568) errors.push(`${at}: year must be 2568`);
    if (si.indicatorCodes?.join(',') !== '1.3.2') errors.push(`${at}: indicatorCodes must be exactly ['1.3.2']`);
    const src = aspectsById.get(si.aspectId);
    if (!src) errors.push(`${at}: aspectId ${si.aspectId} does not resolve to an aspect`);
    else if (!VALID_SIGNIFICANCE.has(si.significance) || si.significance !== src.assessment.significance) {
      errors.push(`${at}: significance must equal source aspect significance ${src.assessment.significance}`);
    }
    if (!si.controlMeasure || !si.controlMeasure.text) errors.push(`${at}: significant issue must retain control information`);
    if (si.projectReference && !canonicalProjects.has(si.projectReference.projectId)) errors.push(`${at}: project reference not canonical`);
    if (!si.sourceTrace || !si.sourceTrace.sourceFile || si.sourceTrace.sourceVersion !== 'derived') {
      errors.push(`${at}: sourceTrace required with sourceVersion "derived"`);
    }
  }

  // ── Project links (1.3.3) — no invented projects ──────────────
  for (const [i, pl] of (data.projectLinks || []).entries()) {
    const at = `projectLinks[${i}] (${pl.id || '?'})`;
    if (!/^pl-\d+$/.test(pl.id)) errors.push(`${at}: id pattern pl-N required`);
    if (ids.has(pl.id)) errors.push(`${at}: duplicate id`);
    ids.add(pl.id);
    if (pl.indicatorCodes?.join(',') !== '1.3.3') errors.push(`${at}: indicatorCodes must be exactly ['1.3.3']`);
    if (!canonicalProjects.has(pl.projectId)) errors.push(`${at}: projectId ${pl.projectId} is not a canonical 1.3.3 project`);
    const src = aspectsById.get(pl.aspectId);
    if (!src) errors.push(`${at}: aspectId ${pl.aspectId} does not resolve`);
    else {
      if (!src.projectReference || src.projectReference.projectId !== pl.projectId) errors.push(`${at}: aspect ${pl.aspectId} does not carry this projectReference`);
      if (pl.projectTitle !== src.projectReference.projectTitle) errors.push(`${at}: projectTitle mismatch`);
      if (pl.controlText !== (src.controlMeasure ? src.controlMeasure.text : null)) errors.push(`${at}: controlText mismatch`);
    }
    if (!pl.sourceTrace || !pl.sourceTrace.sourceFile || pl.sourceTrace.sourceVersion !== 'derived') {
      errors.push(`${at}: sourceTrace required with sourceVersion "derived"`);
    }
  }
  if (data.summary.projectLinkCount !== (data.projectLinks || []).length) {
    errors.push(`summary.projectLinkCount must equal projectLinks.length`);
  }

  // ── Summary cross-checks ──────────────────────────────────────
  const byIO = { input: 0, output: 0 };
  const byDI = { direct: 0, indirect: 0 };
  const byCond = { normal: 0, abnormal: 0, emergency: 0 };
  const bySig = { L: 0, M: 0, H: 0 };
  for (const r of data.records || []) {
    byIO[r.inputOutput] += 1;
    byDI[r.directIndirect] += 1;
    byCond[r.condition] += 1;
    bySig[r.assessment.significance] += 1;
  }
  const s = data.summary || {};
  if (JSON.stringify(s.byInputOutput) !== JSON.stringify(byIO)) errors.push(`summary.byInputOutput mismatch: expected ${JSON.stringify(byIO)}`);
  if (JSON.stringify(s.byDirectIndirect) !== JSON.stringify(byDI)) errors.push(`summary.byDirectIndirect mismatch`);
  if (JSON.stringify(s.byCondition) !== JSON.stringify(byCond)) errors.push(`summary.byCondition mismatch`);
  if (JSON.stringify(s.bySignificance) !== JSON.stringify(bySig)) errors.push(`summary.bySignificance mismatch`);
  if (s.aspectCount !== (data.records || []).length) errors.push(`summary.aspectCount mismatch`);

  // ── Superseded-sheet exclusion ────────────────────────────────
  if (s.supersededExcluded?.sheet !== SUPERSEDED_SHEET) errors.push(`summary.supersededExcluded.sheet must be ${SUPERSEDED_SHEET}`);
  if (s.supersededExcluded?.recordCount !== 55) errors.push(`summary.supersededExcluded.recordCount must be 55`);

  // ── Year isolation: no FY2567/FY2569 leakage in record values ──
  const recordBodies = [
    ...(data.records || []),
    ...(data.activities || []),
    ...(data.significantIssues || []),
    ...(data.projectLinks || []),
  ];
  for (const rec of recordBodies) {
    if (rec.year !== 2568) errors.push(`${rec.id}: year must be 2568`);
  }
  const recordRaw = JSON.stringify(recordBodies);
  for (const leak of ['25(67|69)']) {
    const re = new RegExp(leak);
    if (re.test(recordRaw)) errors.push(`year leakage: record values contain pattern ${leak}`);
  }
  if (data.year !== 2568) errors.push('year must be 2568');

  // ── Report ────────────────────────────────────────────────────
  console.log('=== ENVIRONMENTAL ASPECTS 2568 VALIDATION ===');
  console.log(`Records checked : aspects ${(data.records || []).length}, activities ${(data.activities || []).length}, significant ${(data.significantIssues || []).length}, projectLinks ${(data.projectLinks || []).length}`);
  if (errors.length > 0) {
    console.log(`--- ${errors.length} ERROR(S) ---`);
    errors.forEach((e) => console.log(`  ✗  ${e}`));
    console.log('\nRESULT: FAIL (exit code 1)');
    process.exit(1);
  }
  console.log('RESULT: PASS ✓ (exit code 0)');
}

main();
